import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for AbstractLeastSquaresOptimizer#getRMS.
 * Since the class is abstract and the fields are protected/private, 
 * we use a concrete subclass and reflection to manipulate state for testing.
 */
public class AbstractLeastSquaresOptimizer_getRMS_TriageGen0Test {

    private TestOptimizer optimizer;

    // Concrete implementation for testing purposes
    private static class TestOptimizer extends AbstractLeastSquaresOptimizer {
        @Override
        protected VectorialPointValuePair doOptimize() {
            return null;
        }
    }

    @Before
    public void setUp() {
        optimizer = new TestOptimizer();
    }

    /**
     * Helper method to set private/protected fields via reflection
     */
    private void setField(String fieldName, Object value) throws Exception {
        Field field = AbstractLeastSquaresOptimizer.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(optimizer, value);
    }

    @Test
    public void testGetRMS_StandardCalculation() throws Exception {
        // Setup scenario:
        // residuals = [3.0, 4.0]
        // weights = [1.0, 1.0]
        // rows = 2
        // criterion = (3^2 * 1) + (4^2 * 1) = 9 + 16 = 25
        // RMS = sqrt(25 / 2) = sqrt(12.5) ≈ 3.5355339059327378

        setField("rows", 2);
        setField("residuals", new double[]{3.0, 4.0});
        setField("residualsWeights", new double[]{1.0, 1.0});

        double expected = Math.sqrt(25.0 / 2.0);
        assertEquals(expected, optimizer.getRMS(), 1e-15);
    }

    @Test
    public void testGetRMS_WithWeights() throws Exception {
        // Setup scenario:
        // residuals = [2.0, 2.0]
        // weights = [0.5, 2.0]
        // rows = 2
        // criterion = (2^2 * 0.5) + (2^2 * 2.0) = (4 * 0.5) + (4 * 2.0) = 2 + 8 = 10
        // RMS = sqrt(10 / 2) = sqrt(5) ≈ 2.23606797749979

        setField("rows", 2);
        setField("residuals", new double[]{2.0, 2.0});
        setField("residualsWeights", new double[]{0.5, 2.0});

        double expected = Math.sqrt(5.0);
        assertEquals(expected, optimizer.getRMS(), 1e-15);
    }

    @Test
    public void testGetRMS_ZeroResiduals() throws Exception {
        setField("rows", 3);
        setField("residuals", new double[]{0.0, 0.0, 0.0});
        setField("residualsWeights", new double[]{1.0, 1.0, 1.0});

        assertEquals(0.0, optimizer.getRMS(), 1e-15);
    }

    @Test
    public void testGetRMS_ZeroRows() throws Exception {
        // If rows is 0, criterion is 0, returns sqrt(0/0) which is NaN
        setField("rows", 0);
        setField("residuals", new double[]{});
        setField("residualsWeights", new double[]{});

        assertEquals(Double.NaN, optimizer.getRMS(), 0.0);
    }

    @Test
    public void testGetRMS_SingleElement() throws Exception {
        // residuals = [5.0], weight = [1.0], rows = 1
        // criterion = 25, RMS = sqrt(25/1) = 5
        setField("rows", 1);
        setField("residuals", new double[]{5.0});
        setField("residualsWeights", new double[]{1.0});

        assertEquals(5.0, optimizer.getRMS(), 1e-15);
    }

    @Test
    public void testGetRMS_NegativeResiduals() throws Exception {
        // Residuals are squared, so sign shouldn't matter
        // residuals = [-3.0], weight = [1.0], rows = 1
        // criterion = (-3)^2 * 1 = 9, RMS = 3
        setField("rows", 1);
        setField("residuals", new double[]{-3.0});
        setField("residualsWeights", new double[]{1.0});

        assertEquals(3.0, optimizer.getRMS(), 1e-15);
    }
}
